#!/usr/bin/env node

/*
 * Narrow public compatibility gate for data-only catalog changes.
 *
 * This is intentionally not a general API scanner.  It checks the canonical
 * catalog history, the generated bytes for all five package languages, the
 * package source paths that must remain unchanged for a data merge, and the
 * small version/changelog allowlist used by an optional patch release.
 */

import { createHash } from "node:crypto";
import { existsSync, lstatSync, realpathSync, statSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { dirname, isAbsolute, relative, resolve, sep } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

import {
  compareHistory as compareTokenHistory,
  dataModel as tokenDataModel,
  renderLanguage as renderTokenLanguage,
  validateCatalog as validateTokenCatalog,
  OUTPUTS as TOKEN_OUTPUTS,
} from "./token-catalog.mjs";
import {
  dataModel as dexDataModel,
  validateCatalog as validateDexCatalog,
} from "./dex-catalog.mjs";
import { OUTPUTS as DEX_OUTPUTS, renderLanguage as renderDexLanguage } from "./generate-dex-catalog.mjs";
import { OUTPUTS as RANKING_OUTPUTS, renderLanguage as renderRankingLanguage } from "./generate-token-rankings.mjs";
import { normalizeRubyLockVersion, rubyLockVersion } from "./ruby-lockfile.mjs";
import { validateRankingArtifact } from "./token-rankings.mjs";

const MODULE_DIRECTORY = dirname(fileURLToPath(import.meta.url));
export const REPOSITORY_ROOT = resolve(MODULE_DIRECTORY, "..");

export const COMPATIBILITY_SCHEMA_VERSION = 1;
export const COMPATIBILITY_KIND = "erpc-sdk-public-compatibility-report";
export const RELEASE_VERSION_PATHS = Object.freeze([
  "packages/typescript/package.json",
  "packages/rust/Cargo.toml",
  "packages/python/pyproject.toml",
  "packages/python/src/erpc_sdk/__init__.py",
  "packages/ruby/lib/erpc_sdk/version.rb",
  "packages/ruby/Gemfile.lock",
  "Cargo.lock",
  "CHANGELOG.md",
]);
export const TOKEN_DATA_PATHS = Object.freeze([
  "registry/token-catalog.json",
  "packages/typescript/src/generated/token_catalog.ts",
  "packages/rust/src/generated/token_catalog.rs",
  "packages/python/src/erpc_sdk/_token_catalog_data.py",
  "packages/go/token_catalog_generated.go",
  "packages/ruby/lib/erpc_sdk/generated/token_catalog.rb",
]);
export const DEX_DATA_PATHS = Object.freeze([
  "registry/dex-catalog.json",
  ...Object.values(DEX_OUTPUTS),
]);
export const RANKING_DATA_PATHS = Object.freeze([
  "registry/token-rankings.json",
  ...Object.values(RANKING_OUTPUTS),
]);
export const DATA_RUNTIME_PATHS = Object.freeze([...new Set([
  ...TOKEN_DATA_PATHS,
  ...DEX_DATA_PATHS,
  ...RANKING_DATA_PATHS,
  "registry/discovery-state.json",
  "registry/discovery-admissions.json",
  "registry/pool-observations.json",
])].sort());
export const GENERATED_PATHS = Object.freeze([...new Set([...Object.values(TOKEN_OUTPUTS), ...Object.values(DEX_OUTPUTS), ...Object.values(RANKING_OUTPUTS)])].sort());
export const DEFAULT_RELEASED_TAG = "v0.6.0";
export const DEFAULT_PAIRED_GO_TAG = "packages/go/v0.6.0";
export const DEFAULT_PUBLISHED_PEEL = "d77169fbf9e927d51113af7a2ee51a5c9b10f3fc";

const SHA_RE = /^[0-9a-f]{40}$/u;
const DIGEST_RE = /^[0-9a-f]{64}$/u;
const SEMVER_RE = /^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/u;
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/u;

export class CompatibilityError extends Error {
  constructor(message, code = "COMPATIBILITY_INVALID") {
    super(message);
    this.name = "CompatibilityError";
    this.code = code;
  }
}

function fail(message, code = "COMPATIBILITY_INVALID") {
  throw new CompatibilityError(message, code);
}

function isRecord(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function requireSha(value, label) {
  if (typeof value !== "string" || !SHA_RE.test(value)) fail(`${label} must be a 40-character lowercase SHA`, "INPUT_INVALID");
  return value;
}

function stableValue(value) {
  if (Array.isArray(value)) return value.map(stableValue);
  if (isRecord(value)) return Object.fromEntries(Object.keys(value).sort().map((key) => [key, stableValue(value[key])]));
  return value;
}

export function semanticFingerprint(value) {
  return createHash("sha256").update(JSON.stringify(stableValue(value))).digest("hex");
}

function runnerResult(runner, command, args, root) {
  if (typeof runner === "function") {
    const result = runner(command, args, { cwd: root, encoding: "utf8", stdio: "pipe" });
    if (typeof result === "string") return { status: 0, stdout: result, stderr: "" };
    return { status: result?.status ?? 0, stdout: String(result?.stdout ?? ""), stderr: String(result?.stderr ?? "") };
  }
  const result = spawnSync(command, args, { cwd: root, encoding: "utf8", stdio: "pipe" });
  return { status: result.status ?? 1, stdout: String(result.stdout ?? ""), stderr: String(result.stderr ?? "") };
}

function gitText(root, args, runner, { allowFailure = false } = {}) {
  const result = runnerResult(runner, "git", args, root);
  if (result.status !== 0) {
    if (allowFailure) return null;
    fail(`git ${args.join(" ")} failed: ${result.stderr.trim()}`, "GIT_INVALID");
  }
  return result.stdout.trim();
}

function gitBlob(root, revision, pathValue, runner, { allowFailure = false } = {}) {
  if (typeof pathValue !== "string" || pathValue.startsWith("/") || pathValue.includes("..")) fail("git blob path is invalid", "PATH_INVALID");
  const result = runnerResult(runner, "git", ["show", `${revision}:${pathValue}`], root);
  if (result.status !== 0) {
    if (allowFailure) return null;
    fail(`cannot read ${revision}:${pathValue}`, "GIT_INVALID");
  }
  return result.stdout;
}

function gitCommit(root, revision, runner) {
  const value = gitText(root, ["rev-parse", `${revision}^{commit}`], runner);
  return requireSha(value, `commit ${revision}`);
}

function gitDiffPaths(root, baseSha, headSha, runner) {
  const value = gitText(root, ["diff", "--name-only", `${baseSha}`, `${headSha}`, "--"], runner);
  return [...new Set(value.split(/\r?\n/u).map((pathValue) => pathValue.trim()).filter(Boolean))].sort();
}

function readJsonBlob(root, revision, pathValue, runner, { optional = false } = {}) {
  const text = gitBlob(root, revision, pathValue, runner, { allowFailure: optional });
  if (text === null) return null;
  try { return JSON.parse(text); } catch (error) { fail(`${revision}:${pathValue} is not valid JSON: ${error.message}`, "CATALOG_INVALID"); }
}

function safeContains(rows, old, key) {
  const encoded = JSON.stringify(old);
  return rows.some((entry) => JSON.stringify(entry) === encoded || key && entry?.[key] === old?.[key] && JSON.stringify(entry) === encoded);
}

function projectionPreserved(baseCatalog, headCatalog, kind, { baseTokenCatalog = undefined, headTokenCatalog = undefined } = {}) {
  const base = kind === "token" ? tokenDataModel(baseCatalog) : dexDataModel(baseCatalog, { tokenCatalog: baseTokenCatalog });
  const head = kind === "token" ? tokenDataModel(headCatalog) : dexDataModel(headCatalog, { tokenCatalog: headTokenCatalog });
  const details = {};
  let preserved = true;
  for (const key of Object.keys(base)) {
    if (!Array.isArray(base[key])) continue;
    const missing = base[key].filter((row) => !safeContains(head[key] ?? [], row, kind === "token" ? (key === "assets" ? "assetId" : key === "deployments" ? "deploymentId" : "name") : key === "dexDeployments" ? "dexDeploymentId" : key === "poolDefinitions" ? "poolDefinitionId" : key === "nativeWrapDefinitions" ? "nativeWrapDefinitionId" : "name"));
    details[key] = { oldCount: base[key].length, missingCount: missing.length, missing };
    if (missing.length > 0) preserved = false;
  }
  return { preserved, details };
}

function rankingHistoryPreserved(baseRanking, headRanking) {
  if (!baseRanking) return true;
  if (!headRanking) return false;
  const membership = (catalog) => {
    const result = new Set();
    for (const row of catalog.records ?? []) {
      const ids = Array.isArray(row.deploymentIds) ? row.deploymentIds : row.deploymentId ? [row.deploymentId] : [];
      for (const deploymentId of ids) result.add(`${row.chainId ?? ""}\0${deploymentId}`);
    }
    for (const row of catalog.unranked ?? []) if (row?.deploymentId) result.add(`${row.chainId ?? ""}\0${row.deploymentId}`);
    return result;
  };
  const coverage = (catalog) => new Set((catalog.metadata?.coverage ?? []).map((entry) => typeof entry === "string" ? entry : entry?.chainId ?? entry?.network ?? null).filter(Boolean));
  const headMembership = membership(headRanking);
  const missingMembership = [...membership(baseRanking)].filter((key) => !headMembership.has(key));
  const missingCoverage = [...coverage(baseRanking)].filter((key) => !coverage(headRanking).has(key));
  return missingMembership.length === 0 && missingCoverage.length === 0;
}

function assertDexHistory(headCatalog, baseCatalog) {
  const by = (rows, key) => new Map(rows.map((row) => [row[key], row]));
  const headDex = by(headCatalog.dexDeployments, "dexDeploymentId");
  for (const row of baseCatalog.dexDeployments) {
    const next = headDex.get(row.dexDeploymentId);
    if (!next || JSON.stringify({ protocolId: next.protocolId, name: next.name, chainId: next.chainId, programAddress: next.programAddress, adapterKind: next.adapterKind }) !== JSON.stringify({ protocolId: row.protocolId, name: row.name, chainId: row.chainId, programAddress: row.programAddress, adapterKind: row.adapterKind })) throw new Error(`historical DEX deployment identity changed: ${row.dexDeploymentId}`);
  }
  const headPools = by(headCatalog.poolDefinitions, "poolDefinitionId");
  for (const row of baseCatalog.poolDefinitions) {
    const next = headPools.get(row.poolDefinitionId);
    if (!next || JSON.stringify({ dexDeploymentId: next.dexDeploymentId, chainId: next.chainId, address: next.address, token0DeploymentId: next.token0DeploymentId, token1DeploymentId: next.token1DeploymentId, adapter: next.adapter }) !== JSON.stringify({ dexDeploymentId: row.dexDeploymentId, chainId: row.chainId, address: row.address, token0DeploymentId: row.token0DeploymentId, token1DeploymentId: row.token1DeploymentId, adapter: row.adapter })) throw new Error(`historical pool definition identity changed: ${row.poolDefinitionId}`);
  }
  const headWraps = by(headCatalog.nativeWrapDefinitions, "nativeWrapDefinitionId");
  for (const row of baseCatalog.nativeWrapDefinitions) {
    const next = headWraps.get(row.nativeWrapDefinitionId);
    if (!next || JSON.stringify({ chainId: next.chainId, nativeTokenDeploymentId: next.nativeTokenDeploymentId, wrappedTokenDeploymentId: next.wrappedTokenDeploymentId }) !== JSON.stringify({ chainId: row.chainId, nativeTokenDeploymentId: row.nativeTokenDeploymentId, wrappedTokenDeploymentId: row.wrappedTokenDeploymentId })) throw new Error(`historical native wrap identity changed: ${row.nativeWrapDefinitionId}`);
  }
  const headAliases = new Map(headCatalog.aliases.map((row) => [`${row.namespace}\0${row.name}`, row]));
  for (const row of baseCatalog.aliases) {
    const next = headAliases.get(`${row.namespace}\0${row.name}`);
    if (!next || JSON.stringify({ namespace: next.namespace, name: next.name, dexDeploymentId: next.dexDeploymentId, poolDefinitionId: next.poolDefinitionId }) !== JSON.stringify({ namespace: row.namespace, name: row.name, dexDeploymentId: row.dexDeploymentId, poolDefinitionId: row.poolDefinitionId })) throw new Error(`historical DEX alias changed: ${row.namespace}:${row.name}`);
  }
}

function generatedChecks(root, headSha, tokenCatalog, dexCatalog, ranking, runner) {
  const checks = [];
  let valid = true;
  for (const [language, pathValue] of Object.entries(TOKEN_OUTPUTS)) {
    const expected = renderTokenLanguage(language, tokenCatalog);
    const actual = gitBlob(root, headSha, pathValue, runner, { allowFailure: true });
    const ok = actual !== null && actual === expected;
    checks.push({ path: pathValue, language, catalog: "token", expectedBytes: Buffer.byteLength(expected), actualBytes: actual === null ? null : Buffer.byteLength(actual), exact: ok });
    if (!ok) valid = false;
  }
  for (const [language, pathValue] of Object.entries(DEX_OUTPUTS)) {
    if (dexCatalog === null) continue;
    const expected = renderDexLanguage(language, dexCatalog, { tokenCatalog });
    const actual = gitBlob(root, headSha, pathValue, runner, { allowFailure: true });
    const ok = actual !== null && actual === expected;
    checks.push({ path: pathValue, language, catalog: "dex", expectedBytes: Buffer.byteLength(expected), actualBytes: actual === null ? null : Buffer.byteLength(actual), exact: ok });
    if (!ok) valid = false;
  }
  if (ranking !== null) for (const [language, pathValue] of Object.entries(RANKING_OUTPUTS)) {
    const expected = renderRankingLanguage(language, ranking, { tokenCatalog });
    const actual = gitBlob(root, headSha, pathValue, runner, { allowFailure: true });
    const ok = actual !== null && actual === expected;
    checks.push({ path: pathValue, language, catalog: "ranking", expectedBytes: Buffer.byteLength(expected), actualBytes: actual === null ? null : Buffer.byteLength(actual), exact: ok });
    if (!ok) valid = false;
  }
  return { valid, checks };
}

function packageVersion(text, pathValue) {
  if (text === null) return null;
  try {
    if (pathValue === "packages/typescript/package.json") return JSON.parse(text).version ?? null;
  } catch { return null; }
  if (pathValue === "packages/rust/Cargo.toml") return text.match(/^\[package\][\s\S]*?^version\s*=\s*"([^"]+)"/mu)?.[1] ?? null;
  if (pathValue === "packages/python/pyproject.toml") return text.match(/^\[project\][\s\S]*?^version\s*=\s*"([^"]+)"/mu)?.[1] ?? null;
  if (pathValue === "packages/python/src/erpc_sdk/__init__.py") return text.match(/^__version__\s*=\s*"([^"]+)"$/mu)?.[1] ?? null;
  if (pathValue === "packages/ruby/lib/erpc_sdk/version.rb") return text.match(/^\s*VERSION\s*=\s*"([^"]+)"$/mu)?.[1] ?? null;
  if (pathValue === "packages/ruby/Gemfile.lock") return rubyLockVersion(text);
  if (pathValue === "Cargo.lock") {
    const blocks = text.split(/^\[\[package\]\]\s*$/mu).slice(1).filter((block) => /^name\s*=\s*"erpc-sdk"\s*$/mu.test(block) && !/^source\s*=/mu.test(block));
    return blocks.length === 1 ? blocks[0].match(/^version\s*=\s*"([^"]+)"$/mu)?.[1] ?? null : null;
  }
  return null;
}

function parseVersion(value) {
  if (typeof value !== "string" || !SEMVER_RE.test(value)) return null;
  const [major, minor, patch] = value.split(".").map(Number);
  return { value, major, minor, patch };
}

function regexEscape(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

function changelogOnlyVersionSection(baseText, headText, version) {
  if (baseText === null || headText === null || typeof version !== "string") return false;
  const pattern = new RegExp(`^##\\s+${regexEscape(version)}(?:\\s+[—-]\\s+\\d{4}-\\d{2}-\\d{2})?\\s*$[\\s\\S]*?(?=^##\\s+|(?![\\s\\S]))`, "gmu");
  const matches = [...headText.matchAll(pattern)];
  if (matches.length !== 1 || new RegExp(`^##\\s+${regexEscape(version)}(?:\\s|$)`, "mu").test(baseText)) return false;
  const match = matches[0];
  const withoutSection = headText.slice(0, match.index) + headText.slice(match.index + match[0].length);
  return withoutSection === baseText;
}

function versionsAt(root, revision, runner) {
  const versions = {};
  for (const pathValue of RELEASE_VERSION_PATHS) versions[pathValue] = packageVersion(gitBlob(root, revision, pathValue, runner, { allowFailure: true }), pathValue);
  const values = Object.values(versions).filter(Boolean);
  return { versions, unique: [...new Set(values)] };
}

function cargoLockOnlySdkVersion(baseText, headText) {
  if (baseText === null || headText === null) return false;
  const normalize = (text) => {
    const headings = [...text.matchAll(/^\[\[package\]\]\s*$/gmu)];
    const blocks = [];
    for (let index = 0; index < headings.length; index += 1) {
      const start = headings[index].index + headings[index][0].length;
      const end = headings[index + 1]?.index ?? text.length;
      const block = text.slice(start, end);
      if (/^name\s*=\s*"erpc-sdk"\s*$/mu.test(block) && !/^source\s*=/mu.test(block)) blocks.push({ start, end, block });
    }
    if (blocks.length !== 1) return null;
    const block = blocks[0];
    const versionPattern = /^version\s*=\s*"[^"]+"\s*$/gmu;
    const matches = [...block.block.matchAll(versionPattern)];
    if (matches.length !== 1) return null;
    const replacement = block.block.slice(0, matches[0].index) + 'version = "<VERSION>"' + block.block.slice(matches[0].index + matches[0][0].length);
    return text.slice(0, block.start) + replacement + text.slice(block.end);
  };
  const normalizedBase = normalize(baseText);
  const normalizedHead = normalize(headText);
  return normalizedBase !== null && normalizedBase === normalizedHead;
}

function normalizeVersionText(text, pathValue) {
  if (text === null) return null;
  const patterns = {
    "packages/typescript/package.json": /^(\s*"version"\s*:\s*")[^"]+("\s*,?\s*)$/mu,
    "packages/rust/Cargo.toml": /(^\[package\][\s\S]*?^version\s*=\s*")[^"]+("\s*$)/mu,
    "packages/python/pyproject.toml": /(^\[project\][\s\S]*?^version\s*=\s*")[^"]+("\s*$)/mu,
    "packages/python/src/erpc_sdk/__init__.py": /(^__version__\s*=\s*")[^"]+("\s*$)/mu,
    "packages/ruby/lib/erpc_sdk/version.rb": /(^\s*VERSION\s*=\s*")[^"]+("\s*$)/mu,
  };
  const pattern = patterns[pathValue];
  if (pathValue === "packages/ruby/Gemfile.lock") return normalizeRubyLockVersion(text);
  if (!pattern) return null;
  const matches = [...text.matchAll(new RegExp(pattern.source, `${pattern.flags.replace("g", "")}g`))];
  if (matches.length !== 1) return null;
  return text.replace(pattern, "$1<VERSION>$2");
}

function releaseEditCheck(root, baseSha, headSha, changedPaths, runner) {
  const changedRelease = changedPaths.filter((pathValue) => RELEASE_VERSION_PATHS.includes(pathValue));
  const outsideRelease = changedRelease.filter((pathValue) => !RELEASE_VERSION_PATHS.includes(pathValue));
  const base = versionsAt(root, baseSha, runner);
  const head = versionsAt(root, headSha, runner);
  const versionPaths = RELEASE_VERSION_PATHS.filter((pathValue) => pathValue !== "CHANGELOG.md");
  const versionValues = versionPaths.map((pathValue) => head.versions[pathValue]).filter(Boolean);
  const sameHeadVersion = versionValues.length === versionPaths.length && new Set(versionValues).size === 1;
  const headVersion = sameHeadVersion ? versionValues[0] : null;
  const baseVersion = base.unique.length === 1 ? base.unique[0] : null;
  const baseParsed = parseVersion(baseVersion);
  const headParsed = parseVersion(headVersion);
  const patchStep = Boolean(baseParsed && headParsed && baseParsed.major === headParsed.major && baseParsed.minor === headParsed.minor && headParsed.patch === baseParsed.patch + 1);
  const lockOnly = cargoLockOnlySdkVersion(gitBlob(root, baseSha, "Cargo.lock", runner, { allowFailure: true }), gitBlob(root, headSha, "Cargo.lock", runner, { allowFailure: true }));
  const versionOnlyPaths = Object.fromEntries(versionPaths.map((pathValue) => {
    const before = gitBlob(root, baseSha, pathValue, runner, { allowFailure: true });
    const after = gitBlob(root, headSha, pathValue, runner, { allowFailure: true });
    if (pathValue === "Cargo.lock") return [pathValue, lockOnly];
    return [pathValue, before !== null && after !== null && before !== after && normalizeVersionText(before, pathValue) !== null && normalizeVersionText(before, pathValue) === normalizeVersionText(after, pathValue)];
  }));
  const versionOnly = Object.values(versionOnlyPaths).every(Boolean);
  const changelog = gitBlob(root, headSha, "CHANGELOG.md", runner, { allowFailure: true }) ?? "";
  const baseChangelog = gitBlob(root, baseSha, "CHANGELOG.md", runner, { allowFailure: true });
  const hasSection = headVersion ? new RegExp(`^##\\s+${regexEscape(headVersion)}(?:\\s+[—-]\\s+\\d{4}-\\d{2}-\\d{2})?\\s*$`, "mu").test(changelog) : false;
  const changelogOnly = hasSection && changelogOnlyVersionSection(baseChangelog, changelog, headVersion);
  const onlyAllowlisted = changedPaths.every((pathValue) => DATA_RUNTIME_PATHS.includes(pathValue) || RELEASE_VERSION_PATHS.includes(pathValue));
  return {
    eligible: changedRelease.length > 0 && outsideRelease.length === 0 && onlyAllowlisted && sameHeadVersion && patchStep && versionOnly && lockOnly && changelogOnly,
    changed: changedRelease,
    outside: outsideRelease,
    baseVersion,
    headVersion,
    versions: { base: base.versions, head: head.versions },
    sameHeadVersion,
    patchStep,
    versionOnly,
    versionOnlyPaths,
    cargoLockOnlySdkVersion: lockOnly,
    changelogSection: hasSection,
    changelogOnly,
  };
}

function publishedBaseline(root, releasedTag, runner, releaseEvidence = undefined) {
  if (!releasedTag) return { verified: false, reason: "no released tag was supplied" };
  const rootPeel = gitText(root, ["rev-parse", `${releasedTag}^{commit}`], runner, { allowFailure: true });
  const version = releasedTag.match(/(?:^|\/)v(\d+\.\d+\.\d+)$/u)?.[1] ?? releasedTag.match(/^v(\d+\.\d+\.\d+)$/u)?.[1] ?? null;
  const goTag = version ? `packages/go/v${version}` : null;
  const goPeel = goTag ? gitText(root, ["rev-parse", `${goTag}^{commit}`], runner, { allowFailure: true }) : null;
  const expected = releasedTag === DEFAULT_RELEASED_TAG ? DEFAULT_PUBLISHED_PEEL : null;
  const evidenceMatches = expected
    ? true
    : isRecord(releaseEvidence)
      && releaseEvidence.verified === true
      && releaseEvidence.rootTag === releasedTag
      && releaseEvidence.goTag === goTag
      && releaseEvidence.peelCommit === rootPeel
      && typeof releaseEvidence.publisher === "string"
      && releaseEvidence.publisher.length > 0;
  const pinnedPeelMatches = expected === null || rootPeel === expected && goPeel === expected;
  const verified = Boolean(rootPeel && SHA_RE.test(rootPeel) && goPeel && SHA_RE.test(goPeel) && rootPeel === goPeel && pinnedPeelMatches && evidenceMatches);
  return { verified, tag: releasedTag, goTag, rootPeel: rootPeel ?? null, goPeel: goPeel ?? null, expectedPeel: expected, releaseEvidence: releaseEvidence ?? null, reason: verified ? null : "root and Go release tags are not a verified paired published baseline" };
}

function sourceChangeClassification(changedPaths) {
  const nonGenerated = [];
  const generated = [];
  const data = [];
  for (const pathValue of changedPaths) {
    if (GENERATED_PATHS.includes(pathValue)) generated.push(pathValue);
    if (DATA_RUNTIME_PATHS.includes(pathValue)) data.push(pathValue);
    const packageSource = pathValue.startsWith("packages/") && !GENERATED_PATHS.includes(pathValue) && !RELEASE_VERSION_PATHS.includes(pathValue) && !/(?:^|\/)(?:README|docs?|test|tests?)(?:\/|\.)/iu.test(pathValue);
    const registryImplementation = pathValue.startsWith("registry/") && /\.(?:mjs|schema\.json)$/u.test(pathValue) && !DATA_RUNTIME_PATHS.includes(pathValue);
    if (packageSource || registryImplementation) nonGenerated.push(pathValue);
  }
  return { nonGenerated: [...new Set(nonGenerated)].sort(), generated, data };
}

/** Verify data-only public compatibility between two exact commits. */
export function verifyPublicCompatibility({ root = REPOSITORY_ROOT, baseSha, headSha, releasedTag = undefined, releaseEvidence = undefined, runner = undefined } = {}) {
  const trustedRoot = resolve(root);
  requireSha(baseSha, "baseSha");
  requireSha(headSha, "headSha");
  // Resolve both revisions before reading blobs so an abbreviated or moving
  // ref cannot silently change the comparison during the checks.
  const resolvedBase = gitCommit(trustedRoot, baseSha, runner);
  const resolvedHead = gitCommit(trustedRoot, headSha, runner);
  const changedPaths = gitDiffPaths(trustedRoot, resolvedBase, resolvedHead, runner);
  const classification = sourceChangeClassification(changedPaths);
  const reasons = [];
  let catalogsValid = true;
  const baseToken = readJsonBlob(trustedRoot, resolvedBase, "registry/token-catalog.json", runner);
  const headToken = readJsonBlob(trustedRoot, resolvedHead, "registry/token-catalog.json", runner);
  const baseDex = readJsonBlob(trustedRoot, resolvedBase, "registry/dex-catalog.json", runner, { optional: true });
  const headDex = readJsonBlob(trustedRoot, resolvedHead, "registry/dex-catalog.json", runner, { optional: true });
  const baseRanking = readJsonBlob(trustedRoot, resolvedBase, "registry/token-rankings.json", runner, { optional: true });
  const headRanking = readJsonBlob(trustedRoot, resolvedHead, "registry/token-rankings.json", runner, { optional: true });
  try { validateTokenCatalog(baseToken); validateTokenCatalog(headToken); } catch (error) { catalogsValid = false; reasons.push(`token catalog validation failed: ${error.message}`); }
  if (baseDex || headDex) {
    try {
      if (!baseDex || !headDex) throw new Error("DEX catalog exists at only one side of the comparison");
      validateDexCatalog(baseDex, { tokenCatalog: baseToken }); validateDexCatalog(headDex, { tokenCatalog: headToken });
    } catch (error) { catalogsValid = false; reasons.push(`DEX catalog validation failed: ${error.message}`); }
  }
  if (baseRanking || headRanking) {
    try {
      if (!headRanking) throw new Error("ranking snapshot exists at base but is missing at head");
      if (baseRanking) validateRankingArtifact(baseRanking, { tokenCatalog: baseToken });
      validateRankingArtifact(headRanking, { tokenCatalog: headToken });
    } catch (error) { catalogsValid = false; reasons.push(`ranking snapshot validation failed: ${error.message}`); }
  }
  let historyPreserved = false;
  let projections = { token: null, dex: null };
  if (catalogsValid) {
    try {
      compareTokenHistory(headToken, baseToken);
      projections.token = projectionPreserved(baseToken, headToken, "token");
      historyPreserved = projections.token.preserved;
      if (baseDex && headDex) {
        assertDexHistory(headDex, baseDex);
        projections.dex = projectionPreserved(baseDex, headDex, "dex", { baseTokenCatalog: baseToken, headTokenCatalog: headToken });
        historyPreserved = historyPreserved && projections.dex.preserved;
      }
    } catch (error) { historyPreserved = false; reasons.push(`historical public projection changed: ${error.message}`); }
  }
  const regen = catalogsValid ? generatedChecks(trustedRoot, resolvedHead, headToken, headDex, headRanking, runner) : { valid: false, checks: [] };
  if (!regen.valid) reasons.push("one or more generated outputs do not exactly match the trusted renderer");
  const dataChanged = classification.data.length > 0 || classification.generated.length > 0;
  const catalogDigestChanged = baseToken?.contentDigest !== headToken?.contentDigest
    || baseDex?.contentDigest !== headDex?.contentDigest
    || baseRanking?.metadata?.contentDigest !== headRanking?.metadata?.contentDigest;
  const generatedDataChanged = classification.generated.length > 0;
  const releasePathsChanged = changedPaths.filter((pathValue) => RELEASE_VERSION_PATHS.includes(pathValue));
  const unexpectedPaths = changedPaths.filter((pathValue) => !DATA_RUNTIME_PATHS.includes(pathValue) && !RELEASE_VERSION_PATHS.includes(pathValue));
  const dataCoreEligible = catalogsValid && dataChanged && (catalogDigestChanged || generatedDataChanged) && historyPreserved && regen.valid && classification.nonGenerated.length === 0 && unexpectedPaths.length === 0;
  const dataMergeEligible = dataCoreEligible && releasePathsChanged.length === 0;
  if (!dataMergeEligible) {
    if (classification.nonGenerated.length) reasons.push(`shipping/API/schema/emitter source changed: ${classification.nonGenerated.join(", ")}`);
    if (releasePathsChanged.length) reasons.push("version or changelog edits are outside the data merge candidate");
    if (!dataChanged) reasons.push("no canonical data or generated runtime change is present");
  }
  const baseline = publishedBaseline(trustedRoot, releasedTag, runner, releaseEvidence);
  if (baseline.verified) {
    const ancestor = gitText(trustedRoot, ["merge-base", "--is-ancestor", baseline.rootPeel, resolvedHead], runner, { allowFailure: true });
    if (ancestor === null) {
      baseline.verified = false;
      baseline.reason = "verified paired published baseline is not an ancestor of the candidate head";
    }
  }
  const releaseCheck = releaseEditCheck(trustedRoot, resolvedBase, resolvedHead, changedPaths, runner);
  const changesSincePublished = baseline.verified ? gitDiffPaths(trustedRoot, baseline.rootPeel, resolvedHead, runner) : [];
  const publishedUnexpected = changesSincePublished.filter((pathValue) => !DATA_RUNTIME_PATHS.includes(pathValue) && !RELEASE_VERSION_PATHS.includes(pathValue));
  let publishedCatalogsValid = false;
  let publishedHistoryPreserved = false;
  let publishedProjections = { token: null, dex: null, ranking: null };
  if (baseline.verified) {
    const publishedToken = readJsonBlob(trustedRoot, baseline.rootPeel, "registry/token-catalog.json", runner, { optional: true });
    const publishedDex = readJsonBlob(trustedRoot, baseline.rootPeel, "registry/dex-catalog.json", runner, { optional: true });
    const publishedRanking = readJsonBlob(trustedRoot, baseline.rootPeel, "registry/token-rankings.json", runner, { optional: true });
    try {
      if (!publishedToken || !baseToken || !headToken) throw new Error("published token catalog is unavailable");
      validateTokenCatalog(publishedToken); validateTokenCatalog(headToken);
      if (publishedDex || headDex) {
        if (!publishedDex || !headDex) throw new Error("published DEX catalog exists at only one side of the history");
        validateDexCatalog(publishedDex, { tokenCatalog: publishedToken }); validateDexCatalog(headDex, { tokenCatalog: headToken });
      }
      if (publishedRanking || headRanking) {
        if (!headRanking) throw new Error("published ranking snapshot is missing at candidate head");
        if (publishedRanking) validateRankingArtifact(publishedRanking, { tokenCatalog: publishedToken });
        validateRankingArtifact(headRanking, { tokenCatalog: headToken });
      }
      publishedProjections.token = projectionPreserved(publishedToken, headToken, "token");
      publishedProjections.dex = publishedDex && headDex ? projectionPreserved(publishedDex, headDex, "dex", { baseTokenCatalog: publishedToken, headTokenCatalog: headToken }) : { preserved: true, details: {} };
      publishedProjections.ranking = rankingHistoryPreserved(publishedRanking, headRanking)
        ? { preserved: true }
        : { preserved: false };
      publishedHistoryPreserved = publishedProjections.token.preserved && publishedProjections.dex.preserved && publishedProjections.ranking.preserved;
      publishedCatalogsValid = publishedHistoryPreserved;
    } catch (error) {
      reasons.push(`published public projection validation failed: ${error.message}`);
    }
  }
  // Patch-release eligibility is evaluated from the verified published paired
  // baseline through the candidate head.  It remains independent from the
  // immediate base->head data-merge decision, so a release-only commit after
  // one or more already merged data commits can still be prepared.
  const autoPatchReleaseEligible = baseline.verified && publishedCatalogsValid && publishedHistoryPreserved && releaseCheck.eligible && publishedUnexpected.length === 0 && regen.valid;
  if (!baseline.verified && releasedTag) reasons.push(baseline.reason);
  if (releasedTag && baseline.verified && publishedUnexpected.length > 0) reasons.push(`published baseline includes non-data changes: ${publishedUnexpected.join(", ")}`);
  if (releasedTag && baseline.verified && !publishedHistoryPreserved) reasons.push("published baseline public projections are not preserved at the candidate head");
  if (releasePathsChanged.length > 0 && !releaseCheck.eligible) reasons.push("release edits are outside the narrow eight-file patch/version rule");
  const manualReleaseRequired = dataCoreEligible && !autoPatchReleaseEligible;
  const status = autoPatchReleaseEligible
    ? "AUTO_PATCH_RELEASE_ELIGIBLE"
    : dataMergeEligible
      ? "DATA_MERGE_ELIGIBLE"
      : !dataChanged && catalogsValid && regen.valid
        ? "NO_CHANGE"
        : "MANUAL_RELEASE_REQUIRED";
  return {
    schemaVersion: COMPATIBILITY_SCHEMA_VERSION,
    kind: COMPATIBILITY_KIND,
    status,
    baseSha: resolvedBase,
    headSha: resolvedHead,
    releasedTag: releasedTag ?? null,
    changedPaths,
    classification,
    catalogDigestChanged,
    catalogs: {
      token: { baseDigest: baseToken?.contentDigest ?? null, headDigest: headToken?.contentDigest ?? null },
      dex: { baseDigest: baseDex?.contentDigest ?? null, headDigest: headDex?.contentDigest ?? null },
    },
    generated: regen,
    publicProjections: projections,
    historyPreserved,
    dataCoreEligible,
    dataMergeEligible,
    autoPatchReleaseEligible,
    manualReleaseRequired,
    releaseCheck,
    publishedBaseline: baseline,
    publishedHistoryPreserved,
    publishedPublicProjections: publishedProjections,
    publishedCatalogsValid,
    publishedUnexpectedPaths: publishedUnexpected,
    reasons: [...new Set(reasons)],
    valid: catalogsValid && regen.valid && historyPreserved,
    fingerprint: semanticFingerprint({ baseSha: resolvedBase, headSha: resolvedHead, changedPaths, dataMergeEligible, autoPatchReleaseEligible, generated: regen.checks, reasons }),
  };
}

function parseArguments(args) {
  const options = { root: REPOSITORY_ROOT, baseSha: null, headSha: null, releasedTag: undefined, report: null, format: "text" };
  const seen = new Set();
  const values = new Map([["--base-sha", "baseSha"], ["--head-sha", "headSha"], ["--released-tag", "releasedTag"], ["--report", "report"], ["--root", "root"]]);
  for (let index = 0; index < args.length; index += 1) {
    const key = args[index];
    if (key === "--help") return { ...options, help: true };
    if (key === "--format=json" || key === "--json") { options.format = "json"; continue; }
    if (key === "--format") { if (args[++index] !== "json") fail("--format accepts only json", "USAGE"); options.format = "json"; continue; }
    const property = values.get(key);
    if (!property || seen.has(key)) fail(`unknown or repeated option ${key}`, "USAGE");
    const value = args[++index];
    if (value === undefined || value.startsWith("--")) fail(`${key} requires one value`, "USAGE");
    seen.add(key); options[property] = value;
  }
  if (options.baseSha === null || options.headSha === null) fail("--base-sha and --head-sha are required", "USAGE");
  return options;
}

export function usage() {
  return "Usage: node registry/verify-public-compatibility.mjs --base-sha SHA --head-sha SHA [--released-tag TAG] [--report PATH] [--root DIR] [--format=json]";
}

async function writeReport(root, reportPath, report) {
  if (!reportPath) return;
  const target = isAbsolute(reportPath) ? resolve(reportPath) : resolve(root, reportPath);
  if (!isAbsolute(reportPath) && relative(root, target).startsWith(`..${sep}`)) fail("report path must remain in the repository", "PATH_INVALID");
  try {
    const existing = lstatSync(target);
    if (existing.isSymbolicLink() || !existing.isFile()) fail("report path already exists and is not a regular file", "PATH_INVALID");
    fail("report path already exists; refusing to overwrite an artifact", "PATH_INVALID");
  } catch (error) {
    if (error instanceof CompatibilityError) throw error;
    if (error?.code !== "ENOENT") throw error;
  }
  const parent = resolve(target, "..");
  if (!existsSync(parent) || !statSync(parent).isDirectory()) fail("report path parent must already exist", "PATH_INVALID");
  try { realpathSync(parent); } catch (error) { fail(`report path parent cannot be inspected: ${error.message}`, "PATH_INVALID"); }
  const { writeFile } = await import("node:fs/promises");
  await writeFile(target, `${JSON.stringify(report, null, 2)}\n`, { flag: "wx" });
}

export async function run(argumentsList = process.argv.slice(2)) {
  const options = parseArguments(argumentsList);
  if (options.help) { process.stdout.write(`${usage()}\n`); return null; }
  const report = verifyPublicCompatibility(options);
  await writeReport(resolve(options.root), options.report, report);
  if (options.format === "json" || options.report) process.stdout.write(`${JSON.stringify(report, null, 2)}\n`);
  else process.stdout.write(`${report.status}: ${report.reasons.join("; ")}\n`);
  return report;
}

const invokedPath = process.argv[1] ? pathToFileURL(resolve(process.argv[1])).href : null;
if (invokedPath !== null && import.meta.url === invokedPath) {
  try { await run(); } catch (error) { process.stderr.write(`verify-public-compatibility: ${error.code ? `${error.code}: ` : ""}${error.message}\n`); process.exitCode = error.code === "USAGE" ? 64 : 1; }
}
